      "semantics": {
        "present": true,
        "what": "借据上发生的每一笔豁免，把「线上按余额成分豁免」和「线下豁免还款」两类合在一张表里。",
        "row": {
          "text": "线下豁免是一笔交易一行；线上豁免是一笔交易的某一个余额成分一行，同一个交易流水号会有多行。",
          "grain_columns": [
            "waiver_seq"
          ],
          "unique": "no",
          "note": "两类的序号来自两张不同源表的自增主键，合并后没有去重。"
        },
        "refresh": {
          "cycle": "daily",
          "time": "incremental",
          "how_to_read": "取某一天的豁免用 dt = 那一天；取一段时间把这段的 dt 分区合起来。"
        },
        "scope": [
          {
            "text": "线上豁免：当天的减免明细里记录状态正常的。",
            "rule_refs": [
              "r1"
            ]
          },
          {
            "text": "线下豁免：当天交易主表里交易场景为线下豁免还款的。",
            "rule_refs": [
              "r2"
            ]
          },
          {
            "text": "两类都要能在产品表里找到产品，否则整行不进表。",
            "rule_refs": [
              "r3"
            ]
          }
        ],
        "good_for": [
          "统计每天的豁免笔数与金额",
          "查某个借据被豁免的记录"
        ],
        "not_for": [
          "看豁免申请与审批过程",
          "按豁免类型统计线下豁免：线下没有豁免类型"
        ],
        "watch": [
          {
            "kind": "conflict",
            "text": "「豁免类型」两套码值说法打架：表注释是字母码，SQL 注释是数字码；实际存哪套待确认。",
            "refs": [
              "column:waiver_type"
            ]
          },
          {
            "kind": "conflict",
            "text": "「借据号」两类来源不同：线上取借据号，线下取贷款账号。",
            "refs": [
              "column:loan_no"
            ]
          },
          {
            "kind": "risk",
            "text": "与产品表关联时没有按生效日期过滤，可能一笔变多行。",
            "refs": [
              "rule:r3"
            ]
          },
          {
            "kind": "coverage",
            "text": "只覆盖老核心；新核心的豁免不在这张表里。"
          }
        ],
        "questions": [
          {
            "id": "q1",
            "text": "处理状态 1 是不是「成功」？",
            "about": [
              "column:waiver_status"
            ],
            "status": "answered"
          },
          {
            "id": "q2",
            "text": "豁免类型实际存的是字母码还是数字码？",
            "about": [
              "column:waiver_type"
            ],
            "status": "open"
          },
          {
            "id": "q3",
            "text": "同一产品编码在产品表里会不会有多个版本同时生效？",
            "about": [
              "rule:r3"
            ],
            "status": "open"
          }
        ],
        "rules": [
          {
            "id": "r1",
            "kind": "filter",
            "text": "只收记录状态正常的减免明细",
            "sql": "record_status = 0"
          },
          {
            "id": "r2",
            "kind": "filter",
            "text": "线下只收豁免还款场景",
            "sql": "trade_scene = 'OFFLINE_WAIVE'"
          },
          {
            "id": "r3",
            "kind": "join",
            "text": "找不到产品的交易不进表",
            "sql": "INNER JOIN demo_ods.ods_product_main_df p ON t.prod_cd = p.prod_cd",
            "watch": "没有按生效日期过滤"
          }
        ],
        "downstream": [
          {
            "task": "ads_collection_waiver_daily",
            "table": "demo_ads.ads_collection_waiver_1d"
          }
